#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/controls/container/master_detail_view/master_detail_view_values/master_detail_view_values.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// MasterDetailView's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/master_detail_view.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The requested presentation: automatic (side by side above the layout's compact threshold, else one role at a time), side_by_side, master_only or detail_only; effective_display_mode is the one in use. An unknown mode throws std::invalid_argument and changes nothing.
template <typename Declaring>
struct MasterDetailViewDisplayModeCapability {
    PropertyCell<MasterDetailDisplayMode, MasterDetailViewDisplayModeCapability<Declaring>> display_mode{MasterDetailDisplayMode::automatic};

    static void assign(MasterDetailViewDisplayModeCapability& capability, MasterDetailDisplayMode incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.display_mode), incoming);
        if (!capability.display_mode.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.display_mode));
    }
};

// In a compact automatic presentation, whether the detail role is shown instead of the master; show_master and show_detail write it.
template <typename Declaring>
struct MasterDetailViewCompactDetailVisibleCapability {
    PropertyCell<bool, MasterDetailViewCompactDetailVisibleCapability<Declaring>> compact_detail_visible{};

    static void assign(MasterDetailViewCompactDetailVisibleCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.compact_detail_visible), incoming);
        if (!capability.compact_detail_visible.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.compact_detail_visible));
    }
};

// Every MasterDetailView capability, in the order the declaring class takes them.
template <typename Declaring>
struct MasterDetailViewCapabilities : public MasterDetailViewDisplayModeCapability<Declaring>,
                                      public MasterDetailViewCompactDetailVisibleCapability<Declaring> {};

} // namespace gui_forms
